options.getOption:
// Once años, región por región: el índice de anomalía de INAMHI de cada una de
// las once regiones, una línea por región, cortada donde no se publicó (entre
// 2021 y 2022 no hay nada, y ese vacío es real).
//
// Pinchar una línea, o su nombre en la leyenda, elige esa región: llena
// `zonaSel` como lo hace un clic en el mapa de la pestaña Ahora, y la gráfica
// «Once años de la región elegida» la sigue. Pinchar otra vez la misma la
// suelta. La elegida va en color; las demás quedan en gris, de contexto.
// Si hay una temporada elegida en las gráficas de arriba (`temporada`), su
// enero-abril se sombrea aquí cuando cae dentro de estos once años.
// Columnas: `time`, `zona_id`, `region`, `anomalia`.
// @constants begin
const VAR = 'zonaSel';
// Escritas literales para que Grafana redibuje el panel cuando cambian.
const PICKED = '${zonaSel}';
const SEASON = '${temporada}';
// Una familia de color por gran región: la costa, la sierra, el oriente, Galápagos.
const FAMILY = (name) =>
  name.startsWith('sierra') ? 'orange' : name.startsWith('oriente') ? 'green' : name === 'Galapagos' ? 'purple' : 'blue';
const GAP_DAYS = 30; // más de un mes sin dato: la línea se corta
const UNIT = 'índice de anomalía';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const grey = 'rgba(128, 128, 128, 0.6)';

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const times = col('time').map(Number);
const ids = col('zona_id').map((v) => String(Number(v)));
const names = col('region');
const values = col('anomalia').map((v) => (v == null ? null : Number(v)));

// Una serie por región, con un hueco (null) donde pasó más de GAP_DAYS sin dato.
const regions = [];
const byId = {};
times.forEach((t, i) => {
  let r = byId[ids[i]];
  if (!r) {
    r = byId[ids[i]] = { id: ids[i], name: names[i], data: [] };
    regions.push(r);
  }
  const last = r.data[r.data.length - 1];
  if (last && t - last[0] > GAP_DAYS * 86400000) {
    r.data.push([last[0] + 86400000, null]);
  }
  r.data.push([t, values[i]]);
});
regions.sort((a, b) => a.name.localeCompare(b.name));
const nameOf = Object.fromEntries(regions.map((r) => [r.name, r.id]));

const picked = context.grafana.replaceVariables(PICKED);
const pick = (id) => {
  const same = id === context.grafana.replaceVariables(PICKED);
  location.partial({ ['var-' + VAR]: same ? '' : id }, true);
};

chart.off('click');
chart.on('click', (event) => {
  if (event.componentType === 'series' && nameOf[event.seriesName]) {
    pick(nameOf[event.seriesName]);
  }
});
// La leyenda no oculta series: un clic en un nombre elige la región.
chart.off('legendselectchanged');
chart.on('legendselectchanged', (event) => {
  chart.dispatchAction({ type: 'legendAllSelect' });
  if (nameOf[event.name]) {
    pick(nameOf[event.name]);
  }
});

const season = parseInt(context.grafana.replaceVariables(SEASON), 10);
const first = times.length ? Math.min(...times) : 0;
const lastT = times.length ? Math.max(...times) : 0;
const seasonArea =
  Number.isFinite(season) && Date.UTC(season, 4, 1) > first && Date.UTC(season, 0, 1) < lastT
    ? [[{ xAxis: Date.UTC(season, 0, 1), name: `ene-abr ${season}` }, { xAxis: Date.UTC(season, 4, 1) }]]
    : [];

const series = regions.map((r) => {
  const on = picked === r.id;
  const color = theme.visualization.getColorByName(FAMILY(r.name));
  const shown = !picked || on ? color : grey;
  return {
    name: r.name,
    type: 'line',
    data: r.data,
    connectNulls: false,
    triggerLineEvent: true,
    cursor: 'pointer',
    showSymbol: on,
    symbolSize: 4,
    z: on ? 3 : 2,
    color,
    lineStyle: { width: on ? 2.5 : 1.2, color: shown, opacity: picked && !on ? 1 : 0.85 },
    itemStyle: { color: shown },
    emphasis: { focus: 'series', lineStyle: { width: 2.5 } },
  };
});
series.push({
  name: 'temporada',
  type: 'line',
  data: [],
  silent: true,
  markArea: {
    silent: true,
    itemStyle: { color: 'rgba(128, 128, 128, 0.15)' },
    label: { color: muted, fontSize: 11, position: 'insideTop' },
    data: seasonArea,
  },
});

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 16, top: 56, bottom: 8, containLabel: true },
  legend: {
    top: 0,
    type: 'scroll',
    data: regions.map((r) => r.name),
    textStyle: { color: muted },
    icon: 'roundRect',
    itemWidth: 14,
    itemHeight: 4,
  },
  tooltip: {
    trigger: 'item',
    formatter: (p) => {
      const v = Array.isArray(p.value) ? p.value[1] : p.value;
      if (v == null) return '';
      const d = new Date(p.value[0]).toISOString().slice(0, 10);
      const hint = picked === nameOf[p.seriesName] ? 'pincha para soltarla' : 'pincha para elegirla';
      return `<b>${p.seriesName}</b> · ${d}<br/>${UNIT}: <b>${v.toFixed(2)}</b><br/><span style="opacity:.7">${hint}</span>`;
    },
  },
  xAxis: { type: 'time', axisLabel: { color: muted }, splitLine: { show: false } },
  yAxis: {
    type: 'value',
    name: UNIT + ' (− más seco, + más lluvioso)',
    nameTextStyle: { color: muted, align: 'left' },
    axisLabel: { color: muted },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  series,
};

