options.getOption:
// Cuánto llovió cada temporada (enero a abril), un año por barra, en la
// estación elegida. El color es lo caliente que estuvo el mar frente a Ecuador
// en dic-ene-feb, con los mismos tramos que la gráfica de puntos; gris claro si
// no hay índice para ese año. La línea discontinua es lo normal: la mediana.
//
// Pinchar una barra elige esa temporada (`temporada`): se resalta aquí, en la
// gráfica de puntos y, si cae después de 2015, en la de las regiones. Pinchar
// otra vez la misma la suelta.
// Columnas: `anio`, `mm`, `nino12`.
// @constants begin
const VAR = 'temporada';
// Escrita literal para que Grafana redibuje el panel cuando cambia.
const PICKED = '${temporada}';
const UNIT = 'mm acumulados (ene-abr)';
// El mar frente a Ecuador en dic-ene-feb (Niño 1+2, °C sobre lo normal), en
// cuatro tramos. Los mismos en las dos gráficas: la barra y el punto de una
// temporada tienen el mismo color.
const BREAKS = [-0.5, 0.5, 1.5];
const PIECES = [
  { name: 'mar más frío (< −0,5 °C)', color: 'blue' },
  { name: 'mar normal', color: 'rgba(128, 128, 128, 0.75)' },
  { name: 'más caliente (0,5 a 1,5 °C)', color: 'orange' },
  { name: 'mucho más caliente (> 1,5 °C)', color: 'red' },
];
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const text = theme.colors.text.primary;
const paint = (c) => (c.startsWith('rgba') ? c : theme.visualization.getColorByName(c));
const colorOf = (v) => (v == null ? 'rgba(128, 128, 128, 0.3)' : paint(PIECES[BREAKS.filter((b) => v >= b).length].color));

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const years = col('anio').map(String);
const mm = col('mm').map((v) => (v == null ? null : Number(v)));
const idx = col('nino12').map((v) => (v == null ? null : Number(v)));
const sorted = mm.filter((v) => v != null).sort((a, b) => a - b);
const median = sorted.length ? sorted[Math.floor((sorted.length - 1) / 2)] : null;

const picked = context.grafana.replaceVariables(PICKED);

chart.off('click');
chart.on('click', (event) => {
  if (event.seriesType !== 'bar') return;
  const year = years[event.dataIndex];
  const same = year === context.grafana.replaceVariables(PICKED);
  location.partial({ ['var-' + VAR]: same ? '' : year }, true);
});

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 16, top: 28, bottom: 48, containLabel: true },
  legend: {
    bottom: 0,
    selectedMode: false,
    data: PIECES.map((p) => p.name),
    textStyle: { color: muted, fontSize: 11 },
    itemWidth: 10,
    itemHeight: 10,
  },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: (items) => {
      const i = items[0].dataIndex;
      const sea = idx[i] == null ? 'sin índice' : `${idx[i] > 0 ? '+' : ''}${idx[i].toFixed(2)} °C`;
      const hint = years[i] === picked ? 'pincha para soltarla' : 'pincha para elegirla';
      return `<b>${years[i]}</b><br/>Lluvia ene-abr: <b>${mm[i]} mm</b><br/>Mar en dic-ene-feb: ${sea}<br/><span style="opacity:.7">${hint}</span>`;
    },
  },
  xAxis: { type: 'category', data: years, axisLabel: { color: muted }, axisTick: { show: false } },
  yAxis: {
    type: 'value',
    name: UNIT,
    nameTextStyle: { color: muted, align: 'left' },
    axisLabel: { color: muted },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  series: [
    {
      type: 'bar',
      barWidth: '70%',
      cursor: 'pointer',
      data: mm.map((v, i) => ({
        value: v,
        itemStyle: {
          color: colorOf(idx[i]),
          opacity: picked && picked !== years[i] ? 0.3 : 1,
          borderColor: picked === years[i] ? text : 'transparent',
          borderWidth: picked === years[i] ? 1.5 : 0,
          borderRadius: [2, 2, 0, 0],
        },
      })),
      markLine:
        median == null
          ? undefined
          : {
              silent: true,
              symbol: 'none',
              label: { formatter: `lo normal: ${median} mm`, color: muted, fontSize: 10, position: 'insideStartTop' },
              lineStyle: { type: 'dashed', color: muted },
              data: [{ yAxis: median }],
            },
    },
    // Solo para la leyenda de colores.
    ...PIECES.map((p) => ({ name: p.name, type: 'bar', data: [], color: paint(p.color) })),
  ],
};

