options.getOption:
// Mar más caliente, temporada más lluviosa: cada punto es una temporada. Hacia
// la derecha, el mar frente a Ecuador en dic-ene-feb (Niño 1+2, °C sobre lo
// normal); hacia arriba, la lluvia de enero a abril que vino después. El color
// es el mismo tramo que el de la barra de esa temporada.
//
// Pinchar un punto elige esa temporada (`temporada`), como pinchar su barra:
// se resalta en las dos gráficas. Pinchar otra vez la misma la suelta.
// Columnas: `anio`, `indice`, `mm`.
// @constants begin
const VAR = 'temporada';
// Escrita literal para que Grafana redibuje el panel cuando cambia.
const PICKED = '${temporada}';
const XUNIT = 'Mar frente a Ecuador en dic-ene-feb (°C sobre lo normal)';
const YUNIT = 'lluvia ene-abr (mm)';
// El mar frente a Ecuador en dic-ene-feb (Niño 1+2, °C sobre lo normal), en
// cuatro tramos. Los mismos en las dos gráficas: la barra y el punto de una
// temporada tienen el mismo color.
const BREAKS = [-0.5, 0.5, 1.5];
const PIECES = [
  { name: 'mar más frío (< −0,5 °C)', color: 'blue' },
  { name: 'mar normal', color: 'rgba(128, 128, 128, 0.75)' },
  { name: 'más caliente (0,5 a 1,5 °C)', color: 'orange' },
  { name: 'mucho más caliente (> 1,5 °C)', color: 'red' },
];
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const text = theme.colors.text.primary;
const paint = (c) => (c.startsWith('rgba') ? c : theme.visualization.getColorByName(c));
const colorOf = (v) => paint(PIECES[BREAKS.filter((b) => v >= b).length].color);

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const years = col('anio').map(String);
const xs = col('indice').map(Number);
const ys = col('mm').map(Number);

const picked = context.grafana.replaceVariables(PICKED);

chart.off('click');
chart.on('click', (event) => {
  const year = event.data && event.data.year;
  if (!year) return;
  const same = year === context.grafana.replaceVariables(PICKED);
  location.partial({ ['var-' + VAR]: same ? '' : year }, true);
});

const point = (i) => {
  const on = picked === years[i];
  return {
    value: [xs[i], ys[i]],
    year: years[i],
    symbolSize: on ? 16 : 10,
    itemStyle: {
      color: colorOf(xs[i]),
      opacity: picked && !on ? 0.3 : 0.9,
      borderColor: on ? text : 'rgba(255, 255, 255, 0.6)',
      borderWidth: on ? 2 : 1,
    },
    label: on ? { show: true, formatter: years[i], position: 'top', color: text, fontWeight: 'bold' } : undefined,
    z: on ? 3 : 2,
  };
};

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 24, top: 30, bottom: 28, containLabel: true },
  tooltip: {
    trigger: 'item',
    formatter: (p) => {
      const [x, y] = p.value;
      const hint = p.data.year === picked ? 'pincha para soltarla' : 'pincha para elegirla';
      return `<b>${p.data.year}</b><br/>Mar en dic-ene-feb: ${x > 0 ? '+' : ''}${x.toFixed(2)} °C<br/>Lluvia ene-abr: <b>${y} mm</b><br/><span style="opacity:.7">${hint}</span>`;
    },
  },
  xAxis: {
    type: 'value',
    name: XUNIT,
    nameLocation: 'middle',
    nameGap: 26,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  yAxis: {
    type: 'value',
    name: YUNIT,
    nameTextStyle: { color: muted, align: 'left' },
    axisLabel: { color: muted },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  series: [
    {
      type: 'scatter',
      cursor: 'pointer',
      data: years.map((_, i) => point(i)),
      markLine: {
        silent: true,
        symbol: 'none',
        label: { show: false },
        lineStyle: { type: 'dashed', color: muted, opacity: 0.6 },
        data: [{ xAxis: 0 }],
      },
    },
  ],
};

